import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();
        long k = n * m;
        long l = sc.nextLong();
        long r = sc.nextLong();
        long length = r - l + 1;
        long MOD = 998244353;

        if (k % 2 != 0) {
            System.out.println(powMod(length, n * m, MOD));
        } else {
            long val1 = powMod(length, k, MOD);
            long val2 = powMod(length % 2, k, MOD);
            long inv2 = powMod(2, MOD - 2, MOD);
            long answer = ((val1 + val2) % MOD) * inv2 % MOD;
            System.out.println(answer);
        }
        sc.close();
    }

    static long powMod(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}
